{"path":"book.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>Reserve — Schedule a session</title>
  <style>
    :root{--bg:#fffaf6;--warm:#7a4f37;--soft:#6b5a4e;--card:#fff;--muted:#6b645b}
    *{box-sizing:border-box}
    body{margin:0;background:var(--bg);font-family:system-ui;color:#2b2b2b}
    .wrap{max-width:920px;margin:0 auto;padding:28px}
    header{display:flex;justify-content:space-between;align-items:center}
    .brand{font-weight:700;color:var(--warm)}
    nav a{margin-left:12px;color:var(--muted);text-decoration:none}

    .lead{background:linear-gradient(180deg,rgba(122,79,55,0.04),transparent);padding:18px;border-radius:12px}
    h1{margin:0;color:var(--warm)}
    p.lead{margin-top:8px;color:var(--muted)}

    .booking{display:grid;grid-template-columns:1fr 360px;gap:18px;margin-top:18px}
    .card{background:var(--card);padding:18px;border-radius:12px;box-shadow:0 6px 20px rgba(90,60,40,0.04)}

    .steps{display:flex;flex-direction:column;gap:12px}
    .step{padding:12px;border-left:4px solid rgba(122,79,55,0.06)}

    /* Planner (full) */
    .planner{display:flex;flex-direction:column;gap:10px}
    label{font-size:0.9rem;color:var(--soft)}
    input[type='text'],textarea,select{width:100%;padding:10px;border-radius:8px;border:1px solid rgba(100,80,60,0.08)}
    .multi{display:flex;gap:8px}
    .btn{background:var(--warm);color:#fff;padding:10px;border-radius:9px;border:none;cursor:pointer}
    .secondary{background:#fff;border:1px solid rgba(100,80,60,0.08);color:var(--warm)}

    .reveal{opacity:0;transform:translateY(14px);transition:opacity 520ms,transform 520ms}
    .reveal.is-visible{opacity:1;transform:none}

    footer{margin-top:20px;color:var(--muted)}

    @media(max-width:920px){.booking{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <div class="wrap">
    <header>
      <div class="brand">Quiet Grove</div>
      <nav>
        <a href="index.html">Home</a>
        <a href="services.html">Offerings</a>
        <a href="pricing.html">Investment</a>
        <a href="contact.html">Reach</a>
      </nav>
    </header>

    <section class="lead reveal" aria-labelledby="bookTitle">
      <h1 id="bookTitle">Reserve a short diagnostic or a longer partnership</h1>
      <p class="lead">Choose a quick clarity session to map immediate next steps, or pick a longer container for habit scaffolding over weeks.</p>
    </section>

    <section class="booking">
      <div>
        <div class="card reveal">
          <h3>How it works</h3>
          <div class="steps">
            <div class="step"><strong>Choose:</strong> a diagnostic (30–40m) or a course (4–8 weeks)</div>
            <div class="step"><strong>Sketch:</strong> use the planner to build a plan we can use as a session agenda</div>
            <div class="step"><strong>Book:</strong> send the plan with a booking request at the link that appears in your summary</div>
          </div>
        </div>

        <div class="card reveal" style="margin-top:14px">
          <h3>Ready now</h3>
          <p class="muted">If you prefer a direct booking link, include a short note in your plan summary — it will be part of the message you copy or download.</p>
          <p style="margin-top:12px"><a class="btn" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a></p>
        </div>
      </div>

      <aside class="card reveal">
        <h3>Session Planner</h3>
        <p class="muted">A guided tool to create a concise session agenda and a plain-text summary you can copy or download.</p>

        <form id="full-planner" class="planner" onsubmit="return false;">
          <label>Preferred session type</label>
          <select id="stype">
            <option value="diagnostic">Diagnostic — 30–40 minutes</option>
            <option value="foundations">Foundations — 4 weeks</option>
            <option value="steady">Steady Course — 8 weeks</option>
            <option value="ongoing">Ongoing monthly support</option>
          </select>

          <label>What matters most right now</label>
          <input id="focus" type="text" placeholder="A short sentence — what would change if things were steadier?" />

          <label>Concrete constraints</label>
          <input id="constraints" type="text" placeholder="Time limits, travel, caregiving, or tech limits" />

          <label>Three small next steps (separate with commas)</label>
          <input id="steps" type="text" placeholder="e.g. set bedtime alarm, 10-min walk after lunch, pack lunch for two days" />

          <div style="display:flex;gap:8px">
            <button id="make" class="btn">Make agenda</button>
            <button id="download" class="btn secondary" type="button">Download .txt</button>
            <button id="copy" class="btn secondary" type="button">Copy to clipboard</button>
          </div>

          <label>Plain summary</label>
          <textarea id="out" rows="8" readonly style="font-family:monospace"></textarea>
        </form>
      </aside>
    </section>

    <div class="reveal">
      <div class="card">
        <h4>Notes on working together</h4>
        <p class="muted">Work focuses on outcomes, repeatable habits, and practical scaffolds. Sessions are collaborative: we define small experiments and track simple progress markers.</p>
      </div>
    </div>

    <footer>Contact: {{EMAIL}} • {{PHONE}} • {{CITY}}, {{STATE}}</footer>
  </div>

  <script>
    // Scroll reveal with reduced-motion respect
    (function(){
      if(window.matchMedia('(prefers-reduced-motion: reduce)').matches){
        document.querySelectorAll('.reveal').forEach(n=>n.classList.add('is-visible'));
        return;
      }
      const io = new IntersectionObserver((entries)=>{
        entries.forEach(e=>{ if(e.isIntersecting){ e.target.classList.add('is-visible'); io.unobserve(e.target); } });
      },{threshold:0.08,rootMargin:'-6% 0px'});
      document.querySelectorAll('.reveal').forEach(el=>io.observe(el));
    })();

    // Full Session Planner: build, copy, download
    (function(){
      const make = document.getElementById('make');
      const copyBtn = document.getElementById('copy');
      const download = document.getElementById('download');
      const out = document.getElementById('out');

      function buildText(){
        const type = document.getElementById('stype').value;
        const focus = document.getElementById('focus').value.trim() || '[no focus entered]';
        const constraints = document.getElementById('constraints').value.trim() || 'None noted';
        const steps = document.getElementById('steps').value.trim();
        const stepList = steps ? steps.split(',').map(s=>s.trim()).filter(Boolean) : [];

        const lines = [];
        lines.push('Session agenda — ' + type.replaceAll('-', ' '));
        lines.push('Focus: ' + focus);
        lines.push('Constraints: ' + constraints);
        if(stepList.length){
          lines.push('Planned next steps:');
          stepList.forEach((s,i)=> lines.push((i+1) + '. ' + s));
        } else {
          lines.push('Planned next steps: [not listed]');
        }
